void __sk__std_io_send(sk_string line) {
    if (line.__is_null) {
                printf("null");
            } else {
                printf("%s", line.value);
            }
    return;
}

sk_string __sk__std_io_input(sk_string prompt) {
    if (!prompt.__is_null) {
                printf("%s", prompt.value);
            }
            char buffer[256];
            fgets(buffer, sizeof(buffer), stdin);
            size_t len = strlen(buffer);
            if (len > 0 && buffer[len-1] == '\n') {
                buffer[len-1] = '\0';
            }
            return sk_string_new(buffer);
}

void __sk__sendln(sk_any msg) {
    sk_string t19;
    sk_string t20;

    t19 = any_to_string(msg);
    t20 = sk_string_concat(t19, sk_string_new("\n"));
    free(t19.value);
    __sk__std_io_send(t20);
    free(t20.value);
    return;
}

